mapper.select:
SELECT s.* FROM songs s
INNER JOIN embedding_songs e ON e.song_id = s.id AND e.embedding_type = #{embeddingType}
ORDER BY s.created_at DESC

SELECT DISTINCT

FROM songs s
JOIN song_moods sm ON sm.song_id = s.id
WHERE sm.mood_code = #{moodCode}
  AND (s.era = #{era} OR s.generation = #{generation})
  AND s.genre = #{genre}

      AND LOWER(CONCAT(s.title, ' ', s.artist)) NOT REGEXP LOWER(REPLACE(#{excludedKeywords}, ',', '|'))

ORDER BY s.created_at DESC
LIMIT #{limit}

